const navigation=[{name:'Overview',icon:LayoutDashboard},{name:'My events',icon:CalendarDays},{name:'Venue analysis',icon:ScanLine},{name:'Twin review',icon:ShieldCheck},{name:'Twin editor',icon:PenTool},{name:'Requirements',icon:SlidersHorizontal},{name:'Scene compiler',icon:Boxes},{name:'Layout workspace',icon:Layers3},{name:'Run history',icon:History},{name:'Research evidence',icon:BookOpenCheck}] as const;
