  function reviewPayload(){if(!analysis)throw new Error('Load the source analysis first');const pending=record(analysis.pending_review_template);return {candidate_bundle:analysis.candidate_bundle,review:{contract_id:'COMPONENT1_REVIEWED_TWIN_V1',venue_id:venueId,venue_version:version,source:analysis.candidate_bundle.source,candidate_bundle_sha256:pending.candidate_bundle_sha256,calibration:{method:'isotropic_two_point_controls',controls:JSON.parse(controls),metric_origin_px:JSON.parse(origin)},boundary_px:JSON.parse(boundary),objects:JSON.parse(objects),evidence_artifacts:JSON.parse(evidence),review:{status:reviewOK?'approved':'pending',reviewer_id:reviewer,evidence_ref:reviewRef,scope:'EXTERNAL_RESEARCH_REVIEW',geometry_confirmed:geometryOK,metric_dimensions_confirmed:metricOK}}};}
  async function importReview(f:File){if(!analysis)throw new Error('Analyze the source first');const parsed=jsonObject(JSON.parse(await f.text()));const d=validate('TwinReview',parsed.review??parsed);const src=record(analysis.candidate_bundle.source);for(const [k,v] of Object.entries(src)){if(record(d.source)[k]!==v)throw new Error('Supplied review source differs from current analysis');}if(d.candidate_bundle_sha256!==analysis.pending_review_template.candidate_bundle_sha256)throw new Error('Supplied review belongs to another candidate bundle');setVenueId(d.venue_id);setVersion(d.venue_version);setBoundary(pretty(d.boundary_px));setObjects(pretty(d.objects));setControls(pretty(d.calibration.controls));setOrigin(pretty(d.calibration.metric_origin_px));setEvidence(pretty(d.evidence_artifacts??[]));setReviewer(d.review.reviewer_id);setReviewRef(d.review.evidence_ref);setGeometryOK(d.review.geometry_confirmed);setMetricOK(d.review.metric_dimensions_confirmed);setReviewOK(false);setMessage('Supplied review loaded. Confirm the review explicitly before registration.');}
  function buildRequest():Optimize{if(!twin)throw new Error('A registered reviewed metric Twin is required');if(selectedEventId&&!eventTwinMatches)throw new Error('The current Twin is not linked to this event. Controlled lab geometry cannot stand in for this venue.');if(activeEvent&&activeEvent.type!=='Wedding')throw new Error('The frozen optimizer supports Wedding only; this event remains metadata-only.');if(activeEvent&&activeEvent.venueMode!=='indoor')throw new Error('Outdoor/hybrid optimization is unsupported.');if(!clientOK||!plannerOK||!eventId.trim()||!clientRef.trim()||!plannerRef.trim())throw new Error('Event ID, client/planner provenance and explicit requirement confirmations are required');if(!Number.isInteger(guests)||guests<8||guests>240||guests%8)throw new Error('Guest count must be 8â€“240 in exact eight-seat groups');const hard={minimum_clearance_m:clearance,maximum_mean_stage_distance_m:stageLimit===''?null:Number(stageLimit),maximum_total_movement_m:movementLimit===''?null:Number(movementLimit)};const quantities={round_table:guests/8,chair:guests};return validate('Optimize',{contract_id:'COMPONENT1_PP1_EXECUTABLE_V1',mode:'initial_design',venue_id:twin.venue_id,venue_version:twin.venue_version,twin_sha256:twin.twin_sha256,requirements:{event_id:eventId,event_type:'Wedding',guest_count:guests,seats_per_table:8,quantities,client:{requirement_id:`${eventId}_client`,provenance_ref:clientRef,approval_status:'approved',guest_count:guests,quantities,hard,alternative_preference:preference},planner:{requirement_id:`${eventId}_planner`,provenance_ref:plannerRef,approval_status:'approved',guest_count:guests,quantities,hard,alternative_preference:preference},protected_group_ids:[],protected_object_ids:[]},seed,reference:null,affected_group_ids:[],remove_group_ids:[],permissions:[]});}
  async function execute(q:Optimize){const r=await api.optimize(q);if(r.status!=='success'){await linkEventRun(r.run_id,'non_success');setOutcome(r);setApproved(undefined);setPermission(false);setMessage('Request did not produce a new layout. Last successful output, if present, remains visible.');await refresh();setPage('Layout workspace');return;}if(!r.candidate_layouts.length||!r.candidate_layouts.some(l=>l.layout_id===r.selected_layout_id))throw new Error('Backend success has no valid selected candidate');for(const l of r.candidate_layouts){if(!l.constraint_results.independently_verified||record(r.verification[l.layout_id]).valid!==true)throw new Error('Candidate lacks independent verification');}await linkEventRun(r.run_id,'success');setResult(r);setRequest(q);setViewId(r.selected_layout_id);setTarget(Object.keys(r.candidate_layouts[0].group_centers_m)[0]??'');setOutcome(undefined);setApproved(undefined);setApprovalConsent(false);setPermission(false);setRemoveIds([]);setEditDraft(undefined);await refresh();setPage('Layout workspace');}
  async function validateDraggedGroup(groupId:string,delta:number[]){if(!result||!companionOnline)throw new Error('Start the local layout-edit companion before editing.');if(!editPermission||!editReviewer.trim()||editReason.trim().length<5)throw new Error('Explicit local edit permission, reviewer/operator and a reason of at least five characters are required.');const draft=await api.validateLayoutEdit({run_id:result.run_id,layout_id:viewId,group_id:groupId,delta_m:delta,reviewer_id:editReviewer.trim(),reason:editReason.trim(),explicit_permission:true});if(draft.twin_sha256!==result.twin_sha256||draft.baseline_layout_sha256!==String(selectedMetrics.layout_sha256))throw new Error('Edit draft is not bound to the selected exact run/layout/Twin.');setEditDraft(draft);setMessage(`Validated local edit draft ${draft.draft_id.slice(0,12)} saved. This is not a replacement optimizer run or planner approval.`);}
  async function approve(){if(!result||!selected||!operator.trim()||!approvalEvidence.trim()||!approvalConsent)throw new Error('Explicit reviewer, evidence reference and consent are required');const sha=selectedMetrics.layout_sha256;if(typeof sha!=='string')throw new Error('Backend layout hash is missing');const r=await api.approve(result.run_id,{layout_id:selected.layout_id,layout_sha256:sha,venue_version:result.venue_version,reviewer_id:operator,evidence_ref:approvalEvidence,scope:result.source_domain==='controlled_synthetic'?'SIMULATED_FIXTURE_REVIEW':'EXTERNAL_RESEARCH_REVIEW'});setApproved({id:r.approval_id,run:result.run_id,layout:selected.layout_id,sha});setMessage('Explicit local research review recorded. Identity is not authenticated.');}
  async function revise(remove=false){if(!result||!request||!approved||!isApproved||!permission||!reason.trim())throw new Error('An approval for this exact layout and explicit change permission/reason are required');if(result.source_domain!=='controlled_synthetic')throw new Error('Live real-domain adaptive revision is unsupported');const ids=remove?removeIds:[target];if(!ids.length||ids.some(id=>!selected?.group_centers_m[id]))throw new Error('Select existing group identities');const q=structuredClone(request);q.mode=remove?'guest_change':'adaptive_revision';q.reference={run_id:approved.run,layout_id:approved.layout,layout_sha256:approved.sha,approval_id:approved.id};q.affected_group_ids=remove?[]:ids;q.remove_group_ids=remove?ids:[];q.permissions=ids.map(id=>({group_id:id,action:remove?'remove':'move',approved:true,reviewer_id:operator,reason,scope:'SIMULATED_FIXTURE_REVIEW'}));if(remove){const n=Object.keys(selected!.group_centers_m).length-ids.length;if(n<1)throw new Error('At least one eight-seat group must remain');q.requirements.guest_count=n*8;q.requirements.quantities={round_table:n,chair:n*8};for(const p of [q.requirements.client,q.requirements.planner]){p.guest_count=n*8;p.quantities={round_table:n,chair:n*8};}}await execute(validate('Optimize',q));}
  async function openRun(id:string){const stored=await api.run(id);if(stored.response.status!=='success'){setOutcome(stored.response);setPage('Layout workspace');setMessage('Saved non-success record loaded. Any drawing shown is the last successful run.');return;}const q=validate('Optimize',stored.request);let t:Twin|undefined;try{t=await api.twin(q.venue_id,q.venue_version);}catch(e){if(!(e instanceof ApiError)||e.reason!=='STALE_VENUE_VERSION')throw e;}clearVenue(stored.response.source_domain==='controlled_synthetic'?'lab':'image');setTwin(t);setResult(stored.response);setRequest(q);setViewId(stored.response.selected_layout_id);setTarget(Object.keys(stored.response.candidate_layouts[0].group_centers_m)[0]??'');setEventId(q.requirements.event_id);setGuests(q.requirements.guest_count);setMessage(t?'Stored run retrieved from the backend. A new local review is required before revision.':'Historical run retrieved read-only. Its Twin version is stale; review and revision are disabled.');setPage('Layout workspace');}
  function changeView(id:string){setViewId(id);setApproved(undefined);setApprovalConsent(false);setPermission(false);setEditDraft(undefined);}
  function openEvent(id:string){setSelectedEventId(id);setPage('Event workspace');const p=readEventProjects().find(x=>x.id===id);clearVenue('image');if(p?.analysisId||p?.twinId)void act('Restoring this event’s source and registered Twin',async()=>{if(p.analysisId){const a=await api.analysis(p.analysisId);setAnalysis(a);setAnalysisId(a.analysis_id);}if(p.twinId&&p.twinVersion){setTwin(await api.twin(p.twinId,p.twinVersion));setSource('image');}});}
  function createEvent(){setSelectedEventId('');setPage('Create event');}
