  function attachEvent(p:EventProject){setSelectedEventId(p.id);setEventId(p.id);setGuests(p.guests);setClientRef('');setPlannerRef('');setClientOK(false);setPlannerOK(false);setPage('Requirements');setMessage('Event metadata loaded. Enter separate client/planner provenance and confirm both requirement records; event notes are not approvals.');}
  async function registeredExternalTwin(t:Twin){setTwin(t);setSource('image');clearRun();if(selectedEventId){const p=readEventProjects().find(x=>x.id===selectedEventId);if(p)await persistEvent({...p,twinId:t.venue_id,twinVersion:t.venue_version,status:'active',updatedAt:new Date().toISOString()});}setMessage('Frozen backend accepted this reviewed metric Twin. Reviewer identity is not authenticated and this does not certify safety.');setPage('Requirements');}
